families.make_source:
def make(n):
    # n calls, all the same valid public IPv4 address
    return [["8.8.8.8"] for _ in range(n)]

def make(n):
    ip = "8.8.8.8"          # public IPv4, not excluded
    return [[ip] for _ in range(min(n, 8))]

def make(n):
    # generate n distinct public IPv4 addresses: 1.2.3.i  (i = 0..n-1)
    return [[f"1.2.3.{i}"] for i in range(n)]

def make(n):
    # generate n distinct public IPv4 addresses, e.g. 11.0.0.<i>
    return [[f"11.0.0.{i % 256}"] for i in range(n)]
